/* Pack's art: a raccoon leaning on his suitcase, climbing on as it bulges, pushing it shut, and cheering by a roomy trunk. Each clip is a strip of square frames cut from a generated animation, keyed to
 * transparent WebP; every clip shares one crop, so frames line up across clips. As data URIs so
 * one install brings everything. */

export const PACK_ART = {
  lean: "data:image/webp;base64,",
  fill: "data:image/webp;base64,",
  push: "data:image/webp;base64,",
  cheer:
    "data:image/webp;base64,",
};

export const PACK_FRAMES = {
  /** One frame, in image px. */
  w: 206,
  h: 200,
  clips: {
    lean: { frames: 10, fps: 8 },
    fill: { frames: 16, fps: 10 },
    push: { frames: 5, fps: 10 },
    cheer: { frames: 8, fps: 8 },
  },
} as const;
